// Public JSON job feeds per ATS. Providers without a public JSON feed get no URL and are skipped.
const a = $json; const t = a.ats_token;
const feeds = {
  greenhouse: t => 'https://boards-api.greenhouse.io/v1/boards/' + t + '/jobs?content=true',
  lever: t => 'https://api.lever.co/v0/postings/' + t + '?mode=json',
  ashby: t => 'https://api.ashbyhq.com/posting-api/job-board/' + t,
  workable: t => 'https://apply.workable.com/api/v1/widget/accounts/' + t + '?details=true',
  recruitee: t => 'https://' + t + '.recruitee.com/api/offers/',
  smartrecruiters: t => 'https://api.smartrecruiters.com/v1/companies/' + t + '/postings?limit=100'
};
const f = feeds[a.ats_provider];
return { json: { ...a, feed_url: (f && t) ? f(t) : null } };

// Six feed shapes → one row shape that intel_apply_jobs understands (account_id carried through).
const a = $('Feed URL').item.json;
let p = null; try { p = JSON.parse(String($json.body || '')); } catch (e) { p = null; }
const strip = h => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&amp;|&#39;|&quot;/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
const day = v => { if (!v) return null; const d = new Date(typeof v === 'number' ? v : String(v)); return isNaN(d) ? null : d.toISOString().slice(0, 10); };
const rows = [];
const push = (o) => rows.push({ account_id: a.account_id, source: 'ats_' + a.ats_provider, ...o });
if (p) switch (a.ats_provider) {
  case 'greenhouse': for (const j of (p.jobs || [])) push({ id: j.absolute_url, url: j.absolute_url, title: j.title, location: (j.location || {}).name, postedDate: day(j.first_published || j.updated_at), descriptionText: strip(j.content), employmentType: null }); break;
  case 'lever': for (const j of (Array.isArray(p) ? p : [])) push({ id: j.hostedUrl, url: j.hostedUrl, title: j.text, location: (j.categories || {}).location, countryCode: j.country || null, postedDate: day(j.createdAt), descriptionText: String(j.descriptionPlain || '').slice(0, 4000), employmentType: (j.categories || {}).commitment, workplaceType: j.workplaceType }); break;
  case 'ashby': for (const j of (p.jobs || [])) push({ id: j.jobUrl, url: j.jobUrl, title: j.title, location: j.location, postedDate: day(j.publishedAt), descriptionText: String(j.descriptionPlain || '').slice(0, 4000), employmentType: j.employmentType, workplaceType: j.isRemote ? 'Remote' : null }); break;
  case 'workable': for (const j of (p.jobs || [])) push({ id: j.url, url: j.url, title: j.title, location: [j.city, j.country].filter(Boolean).join(', '), countryCode: null, postedDate: day(j.published_on), descriptionText: strip(j.description), employmentType: j.employment_type, workplaceType: j.telecommuting ? 'Remote' : null }); break;
  case 'recruitee': for (const j of (p.offers || [])) push({ id: j.careers_url, url: j.careers_url, title: j.title, location: j.location, countryCode: j.country_code, postedDate: day(j.published_at), descriptionText: strip(j.description), employmentType: j.employment_type_code, workplaceType: j.remote ? 'Remote' : null }); break;
  case 'smartrecruiters': for (const j of (p.content || [])) push({ id: 'https://jobs.smartrecruiters.com/' + a.ats_token + '/' + j.id, url: 'https://jobs.smartrecruiters.com/' + a.ats_token + '/' + j.id, title: j.name, location: [(j.location || {}).city, (j.location || {}).country].filter(Boolean).join(', '), countryCode: (j.location || {}).country, postedDate: day(j.releasedDate), descriptionText: '', employmentType: (j.typeOfEmployment || {}).label, workplaceType: (j.location || {}).remote ? 'Remote' : null }); break;
}
return { json: { batch_id: 'ats-' + a.ats_provider + '-' + a.ats_token, items: rows, count: rows.length, http: $json.statusCode || null } };
